// RustboroCity_DevonCorp_3F (zone 577): generated by converter/gen_interiors.py from Sapphire's simple people and signs.
// Messages: src/text/script/0368_room_RustboroCity_DevonCorp_3F.txt
// Story (chapter Ch2, Sapphire data/maps/RustboroCity_DevonCorp_3F/scripts.inc) after the "// ---- story" line:
// scripts 3-6, text lines 2-15. People (Mr. Stone uid 1, the employee uid 2) and the desk sign: data/story/ch2.json.
// Room origin (1,0): zone tile = Sapphire tile + (1,0).
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_key_items.h"
#include "hoenn_story.inc"

    ScriptEntry Script_1
    ScriptEntry Script_2
    ScriptEntry DV3_Arrival         // 3: RustboroCity_DevonCorp_3F_OnWarp/OnFrame (reserved by Rustboro's warp)
    ScriptEntry DV3_MrStone         // 4: RustboroCity_DevonCorp_3F_EventScript_MrStone
    ScriptEntry DV3_Employee        // 5: RustboroCity_DevonCorp_3F_EventScript_Employee
    ScriptEntry DV3_MrStoneDesk     // 6: Mr. Stone's invisible second object (15,5): talked to across the desk
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 0, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt

Script_2:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 1, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
// ---- story
#define DV3_STONE 1
#define DV3_EMPLOYEE 2

// Rustboro's ReturnGoods warps here (warp MAP_RUSTBORO_CITY_DEVON_CORP_3F, 255, 2, 2) and reserves this script: on
// the black screen the employee takes his OnTransition spot (setobjectxyperm 2, 3, 2, facing left) and the player
// faces east (OnWarp), then the screen fades in and the OnFrame scene (VAR_DEVON_CORP_3F_STATE 0) plays.
DV3_Arrival:
    h_lock
    h_goto_if_ne VAR_DEVON_CORP_3F_STATE, 0, L_DV3_ArrivalDone
    ActorSetGPos DV3_EMPLOYEE, 3 + 1, 0, 2, 2
    FadeInBlack
    FadeWait
    VMJump L_DV3_MeetPresident
L_DV3_ArrivalDone:
    FadeInBlack
    FadeWait
    h_release

L_DV3_MeetPresident:                // RustboroCity_DevonCorp_3F_EventScript_MeetPresident
    h_msgbox_actor 2, DV3_EMPLOYEE  // This is the Devon Corporation's third floor... Could you wait here a second?
    h_closemessage
    h_applymovement DV3_EMPLOYEE, Mv_DV3_EmployeeWalkOffscreen
    h_waitmovement
    h_delay 80
    h_applymovement DV3_EMPLOYEE, Mv_DV3_EmployeeReturnToPlayer
    h_waitmovement
    h_msgbox_actor 3, DV3_EMPLOYEE  // Our President would like to have a word with you. Please come with me.
    h_closemessage
    h_playbgm MUS_FOLLOW_ME
    h_applymovement DV3_EMPLOYEE, Mv_DV3_LeadPlayerToPresident
    h_applymovement 255, Mv_DV3_PlayerFollowToPresident
    h_waitmovement
    h_msgbox_actor 4, DV3_EMPLOYEE  // Please, go ahead.
    h_closemessage
    h_fadedefaultbgm
    h_applymovement DV3_EMPLOYEE, Mv_DV3_EmployeeFaceDesk
    h_applymovement 255, Mv_DV3_PlayerApproachDesk
    h_waitmovement
    h_msgbox_actor 5, DV3_STONE     // I'm Mr. Stone, the President of the Devon Corporation...
    h_closemessage                  // (Black 2: the item script opens its own window)
    h_giveitem ITEM_LETTER
    h_msgbox_actor 6, DV3_STONE     // Mr. Stone: ...That's why I want you to have this!
    h_closemessage
    h_give_pokenav                  // playfanfare + "{PLAYER} received a PokéNav." (line 7): the PokéNav is Black 2's
                                    // Xtransceiver renamed (user decision), given by Black 2's own obtain sequence
    h_setflag FLAG_SYS_POKENAV_GET
    h_setflag FLAG_RECEIVED_POKENAV
    ItemAdd 442, 1, HLIB_TMP                // + Black 2's Town Map (ITEM_TOWN_MAP 442): Sapphire's region map lives in the
                                            // PokéNav, so the map app comes with it, silently (lead, 2026-10-08; notes/TOWN_MAP.md)
    h_msgbox_actor 8, DV3_STONE     // Mr. Stone: That device... It's a Pokémon Navigator, or PokéNav for short...
#ifdef HOENN_EMERALD                // ...ExplainPokenavRestUp (longer than Sapphire's: rest up), the party is healed, then the send-off
    h_closemessage
    h_heal_party_fade               // call Common_EventScript_OutOfCenterPartyHeal
    h_buffer_player
    h_msgbox_actor 16, DV3_STONE    // Mr. Stone: Well, then, <player>, go with caution and care!
#endif
    h_setflag FLAG_HIDE_TUNNER_DIGGER_ROUTE116
    h_clearflag FLAG_HIDE_BOYFRIEND_RUSTURF_TUNNEL
    h_clearflag FLAG_HIDE_GIRLFRIEND_RUSTURF_TUNNEL
    h_clearflag FLAG_HIDE_MR_BRINEY_ROUTE104_HOUSE
    h_clearflag FLAG_HIDE_PEEKO_BRINEY_HOUSE
    h_setvar VAR_BRINEY_LOCATION, 1
    h_clearflag FLAG_HIDE_RIVAL_RUSTBORO
    h_setvar VAR_DEVON_CORP_3F_STATE, 1
#ifdef HOENN_EMERALD                // Emerald (emerald_ch0_3): Scott leaves the Pokémon School; VAR_RUSTBORO_STATE 6, then 7 at once (the
    h_setflag FLAG_HIDE_RUSTBORO_CITY_POKEMON_SCHOOL_SCOTT   // scientist's PokéNav tutorial scene is dropped, decision 3A: his
    h_setvar VAR_RUSTBORO_STATE, 7  // OnFrame state 6 -> 7 and VAR_ROUTE104_STATE 1): the rival waits at the south end of Rustboro
    h_setvar VAR_ROUTE104_STATE, 1
#endif
    h_release

DV3_MrStone:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    VMCall Sub_DV3_MrStoneTalk
    h_turnobject DV3_STONE, 2       // Common_Movement_FaceOriginalDirection (MOVEMENT_TYPE_FACE_LEFT)
    h_release

DV3_MrStoneDesk:                    // the invisible object: Mr. Stone answers from behind his desk
    h_lock
    SEPlay SEQ_SE_MESSAGE
    VMCall Sub_DV3_MrStoneTalk
    h_release

Sub_DV3_MrStoneTalk:
    h_goto_if_set FLAG_RECEIVED_EXP_SHARE, L_DV3_MrStoneAfterFavor
    h_goto_if_set FLAG_DELIVERED_STEVEN_LETTER, L_DV3_GiveExpShare
    h_msgbox_actor 9, DV3_STONE     // Mr. Stone: I'm counting on you!
    h_closemessage
    VMReturn
L_DV3_GiveExpShare:                 // RustboroCity_DevonCorp_3F_EventScript_GiveExpShare
    h_msgbox_actor 10, DV3_STONE    // Mr. Stone: You delivered my Letter? Thank you kindly!...
    h_closemessage                  // (Black 2: the item script opens its own window)
    h_giveitem ITEM_EXP_SHARE
    h_goto_if_eq HLIB_RESULT, 0, L_DV3_BagFull
    h_setflag FLAG_RECEIVED_EXP_SHARE
    FlagSet FLAG_EXP_SHARE_ON       // the hack's Gen 6 Exp. Share, given switched on (b2tools/patches/exp_share.py)
    h_msgbox_actor 11, DV3_STONE    // Mr. Stone: A Pokémon holding that Exp. Share...
    h_closemessage
    VMReturn
L_DV3_BagFull:                      // Common_EventScript_ShowBagIsFull (release + end: no turn back)
    h_msgbox_actor 15, DV3_STONE    // Too bad! The Bag is full...
    h_release
L_DV3_MrStoneAfterFavor:
    h_msgbox_actor 12, DV3_STONE    // Mr. Stone: Since my youth, I've immersed myself in work...
    h_closemessage
    VMReturn

DV3_Employee:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_RECEIVED_REPEAT_BALL, L_DV3_EmployeeBalls
    h_msgbox 13                     // If you visit the Shipyard in Slateport, you should go see Capt. Stern.
    h_release
L_DV3_EmployeeBalls:
    h_msgbox 14                     // Devon's new products, the Repeat Ball and Timer Ball...
    h_release

    .balign 4, 0
Mv_DV3_LeadPlayerToPresident:       // RustboroCity_DevonCorp_3F_Movement_LeadPlayerToPresident
    walk_right 3
    walk_down
    walk_right 9
    walk_in_place_fastest_left
    step_end
Mv_DV3_EmployeeFaceDesk:
    delay_16
    walk_in_place_fastest_down
    step_end
Mv_DV3_EmployeeWalkOffscreen:
    walk_right 3
    walk_down
    walk_right 4
    step_end
Mv_DV3_EmployeeReturnToPlayer:
    walk_left 4
    walk_up
    walk_left 3
    step_end
Mv_DV3_PlayerFollowToPresident:
    walk_right 4
    walk_down
    walk_right 8
    step_end
Mv_DV3_PlayerApproachDesk:
    delay_16 2
    walk_down 2
    walk_in_place_fastest_right
    step_end
    .balign 4, 0
